/// What the behavior operations of fixture-agents-api run on: a pool of
/// fixture-agents-db, its database, which `Implementations::new` takes.
#[derive(Clone)]
pub struct Behaviors {
    pool: Pool,
}

impl Behaviors {
    /// The behavior operations' runner on `pool`, a pool of fixture-agents-db.
    pub fn new(pool: Pool) -> Self {
        Self { pool }
    }
}

/// The core with the behaviors superschematic-rules-behaviors registers,
/// built once per process: a `Core` is `Send` and `Sync`, so one serves
/// every request.
fn core() -> &'static Core {
    static CORE: OnceLock<Core> = OnceLock::new();
    CORE.get_or_init(superschematic_rules_behaviors::core)
}

/// RULES_LAYOUT, read once per process.
///
/// # Panics
///
/// When the document does not read: the build wrote it, so that is a
/// defect of the build.
fn layout() -> &'static Layout {
    static LAYOUT: OnceLock<Layout> = OnceLock::new();
    LAYOUT.get_or_init(|| match Layout::from_json(RULES_LAYOUT) {
        Ok(layout) => layout,
        Err(err) => panic!("the behaviors' layout, RULES_LAYOUT, does not read: {err}"),
    })
}

/// The caller the core runs an operation as (D103): the route's principal
/// with the permissions it holds, each once; else a calling service
/// standing in for an end user, which holds none (D37); else no one.
fn caller(ctx: &RequestContext) -> Caller {
    if let Some(principal) = &ctx.principal {
        let mut permissions: Vec<&str> = Vec::new();
        for permission in &principal.permissions {
            if !permissions.contains(&permission.as_str()) {
                permissions.push(permission);
            }
        }
        return Caller::new(principal.subject.clone(), permissions);
    }
    if let Some(service) = &ctx.service_caller {
        return Caller::standing_in(service.deployable.clone());
    }
    Caller::new("", Vec::<String>::new())
}

/// Runs `operation` of the use `use_id` on the row of `type_name` whose key
/// is `key`, with `params`, in a transaction of the pool, as the request's
/// caller, and returns its result once the transaction commits. The key
/// goes to the core in its wire form, its JSON string. A refusal of the
/// core or the adapter rolls the transaction back and is the problem of its
/// status, code, message and details; a refusal of status 500 or of no
/// error status, a failure of the database, the pool's included, and a
/// result that does not read are logged and answered as the server's
/// internal error, as the Go and TypeScript servers answer them.
pub(crate) async fn run_operation<K, P, R>(
    behaviors: &Behaviors,
    ctx: &RequestContext,
    type_name: &str,
    key: &K,
    use_id: &str,
    operation: &str,
    params: &P,
) -> Result<R, ApiError>
where
    K: Serialize + ?Sized,
    P: Serialize + ?Sized,
    R: DeserializeOwned,
{
    let key = match serde_json::to_value(key).map_err(internal)? {
        Value::String(key) => key,
        other => other.to_string(),
    };
    let params = serde_json::to_value(params).map_err(internal)?;
    let mut client = behaviors.pool.get().await.map_err(internal)?;
    let tx = client.transaction().await.map_err(internal)?;
    let host = Host::new(core(), layout());
    let ran = postgres::run_operation(
        &host,
        &*tx,
        type_name,
        &key,
        use_id,
        operation,
        params,
        caller(ctx),
    )
    .await;
    match ran {
        Ok(result) => {
            tx.commit().await.map_err(internal)?;
            serde_json::from_value(result).map_err(internal)
        }
        // Dropping the transaction rolls it back.
        Err(Error::Refused(refusal)) if is_problem(refusal.status) => Err(problem(*refusal)),
        Err(err) => Err(internal(err)),
    }
}

/// Runs `operation` of the use `use_id` on the table of `type_name` as a
/// whole (D104), a command without a row, with `params`, in a transaction of
/// the pool, as the request's caller, and returns its result once the
/// transaction commits: the core writes each row it reaches through a call
/// on that row, each held to its version, and a read-only one writes
/// nothing. Its refusals and failures are answered as `run_operation`'s.
pub(crate) async fn run_table_operation<P, R>(
    behaviors: &Behaviors,
    ctx: &RequestContext,
    type_name: &str,
    use_id: &str,
    operation: &str,
    params: &P,
) -> Result<R, ApiError>
where
    P: Serialize + ?Sized,
    R: DeserializeOwned,
{
    let params = serde_json::to_value(params).map_err(internal)?;
    let mut client = behaviors.pool.get().await.map_err(internal)?;
    let tx = client.transaction().await.map_err(internal)?;
    let host = Host::new(core(), layout());
    let ran = postgres::run_table_operation(
        &host,
        &*tx,
        type_name,
        use_id,
        operation,
        params,
        caller(ctx),
        &ExecuteOptions::default(),
    )
    .await;
    match ran {
        Ok(result) => {
            tx.commit().await.map_err(internal)?;
            serde_json::from_value(result).map_err(internal)
        }
        // Dropping the transaction rolls it back.
        Err(Error::Refused(refusal)) if is_problem(refusal.status) => Err(problem(*refusal)),
        Err(err) => Err(internal(err)),
    }
}

/// Runs `operation` as `run_operation` does, with the caller's preconditions
/// its input presents (D16, D104): the input's `preconditions` member, each
/// use's entry by its use id (`{"Lease": {"token": 3}}`), taken out of the
/// parameters and handed to the core with the command, which checks each
/// against its use's behavior before it reads the row and hands it to that
/// use's guard, a malformed one refused as `invalid_argument`.
pub(crate) async fn run_operation_with_preconditions<K, P, R>(
    behaviors: &Behaviors,
    ctx: &RequestContext,
    type_name: &str,
    key: &K,
    use_id: &str,
    operation: &str,
    input: &P,
) -> Result<R, ApiError>
where
    K: Serialize + ?Sized,
    P: Serialize + ?Sized,
    R: DeserializeOwned,
{
    let key = match serde_json::to_value(key).map_err(internal)? {
        Value::String(key) => key,
        other => other.to_string(),
    };
    let mut params = serde_json::to_value(input).map_err(internal)?;
    let options = ExecuteOptions {
        preconditions: presented(&mut params),
        ..ExecuteOptions::default()
    };
    let mut client = behaviors.pool.get().await.map_err(internal)?;
    let tx = client.transaction().await.map_err(internal)?;
    let host = Host::new(core(), layout());
    let ran = postgres::run_operation_with(
        &host,
        &*tx,
        type_name,
        &key,
        use_id,
        operation,
        params,
        caller(ctx),
        &options,
    )
    .await;
    match ran {
        Ok(result) => {
            tx.commit().await.map_err(internal)?;
            serde_json::from_value(result).map_err(internal)
        }
        // Dropping the transaction rolls it back.
        Err(Error::Refused(refusal)) if is_problem(refusal.status) => Err(problem(*refusal)),
        Err(err) => Err(internal(err)),
    }
}

/// The caller's preconditions an input presents, taken out of it (D16,
/// D104): its `preconditions` member's entries by use id, a null one left
/// out, as the Go and TypeScript servers read them; none for an input
/// without the member.
fn presented(input: &mut Value) -> Map<String, Value> {
    match input
        .as_object_mut()
        .and_then(|input| input.remove("preconditions"))
    {
        Some(Value::Object(entries)) => entries
            .into_iter()
            .filter(|(_, entry)| !entry.is_null())
            .collect(),
        _ => Map::new(),
    }
}

/// Whether a refusal of `status` is answered as its problem: an error
/// status, 400 to 599, other than 500, which is the server's own.
fn is_problem(status: u16) -> bool {
    (400..=599).contains(&status) && status != 500
}

/// The problem of a refusal: its status, code, message and details.
fn problem(refusal: Refusal) -> ApiError {
    let Refusal {
        code,
        status,
        message,
        details,
        ..
    } = refusal;
    let status = StatusCode::from_u16(status).unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
    let error = ApiError::new(status, code.as_str(), message);
    match details {
        Some(details) => error.with_details(Value::Object(*details)),
        None => error,
    }
}

/// Logs `err` and answers the server's internal error, with none of its
/// text.
fn internal(err: impl std::fmt::Display) -> ApiError {
    tracing::error!(error = %err, "behavior operation failed");
    ApiError::internal("An unexpected error occurred")
}

/// The caller JobDeadlines's commands run as (D103): the worker, not a user,
/// holding the permissions its @behaviorWorker grants.
fn job_deadlines_caller() -> Caller {
    Caller::new("fixture-agents-api/JobDeadlines", Vec::<String>::new())
}

/// The deadline queue of the behavior worker JobDeadlines (D103),
/// fixture-agents-db's JobDeadline, on `pool`, a pool of fixture-agents-db:
/// a queue whose handler, `run_job_deadlines_deadline`, completes each message
/// itself, which `worker::run_worker` runs.
pub fn job_deadlines_deadlines(
    pool: &Pool,
) -> Result<SelfCompleting<PostgresQueue<JobDeadline>>, BoxError> {
    let definition = QueueDefinition::parse(JOB_DEADLINE_QUEUE)?;
    let queue = PostgresQueue::new(pool.clone(), definition);
    Ok(SelfCompleting::new(queue))
}

/// Runs a claimed deadline of Job through the behaviors' core on a
/// transaction of the pool, as the worker, at the later of now and the time
/// it was armed to fall due at, its message's completion in the same commit
/// (D103). A deadline armed or cleared since the claim, or of a row or a use
/// that is gone, runs nothing, and a fire a guard vetoes is released, due
/// again in a minute, each of which it logs; a refusal or a failure of the
/// database rolls the transaction back and fails the message, which the
/// queue retries after its backoff.
pub async fn run_job_deadlines_deadline(
    pool: &Pool,
    claimed: Claimed<JobDeadline>,
) -> Result<(), BoxError> {
    let deadline = deadline_of(&claimed.message)?;
    let claim = Claim {
        id: claimed.id.clone(),
        token: claimed.token.clone(),
    };
    let mut client = pool.get().await?;
    let tx = client.transaction().await?;
    let host = Host::new(core(), layout());
    let run = postgres::run_deadline(
        &host,
        &*tx,
        "Job",
        &deadline,
        job_deadlines_caller(),
        Some(&claim),
    )
    .await?;
    tx.commit().await?;
    if !matches!(run, DeadlineRun::Ran(_)) {
        tracing::info!(
            message = claimed.id.as_str(),
            why = run.why(),
            "deadline ran nothing"
        );
    }
    Ok(())
}

